const escapeHtml = value => String(value ?? '').replace(/[&<>'"]/g, char => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', "'":'&#39;', '"':'&quot;' })[char]);
function setBusy(on, label='잠시만요…') { busyCount=Math.max(0,busyCount+(on?1:-1)); $('#busy').hidden=!busyCount; $('#busy span:last-child').textContent=label; }
function toast(message) { $('#toast').textContent=message; $('#toast').classList.add('on'); clearTimeout(toastTimer); toastTimer=setTimeout(()=>$('#toast').classList.remove('on'),3200); }
function applyTheme(theme) { const dark=theme==='dark'; document.documentElement.classList.toggle('dark',dark); document.body.classList.toggle('dark',dark); localStorage.setItem('ready-theme',theme); }
function clearSession() { localStorage.removeItem(SESSION_KEY); state.token=''; state.data=null; }
async function call(op,data={},token=state.token,label='잠시만요…') { setBusy(true,label); try{return await readyApi(op,data,token);}finally{setBusy(false);} }
async function safely(job,{auth=true}={}) { try{return await job();}catch(error){if(auth&&error.status===401){clearSession();showLogin();}toast(error.message||'요청을 처리하지 못했습니다.');return null;} }
function showLogin() { $('#admin-login').hidden=false; $('#admin-nav').hidden=true; $('#admin-logout').hidden=true; $$('.view').forEach(view=>view.classList.remove('on')); }
function route(name) { state.route=name; $$('.view').forEach(view=>view.classList.toggle('on',view.id===`v-${name}`)); $$('.navbtn').forEach(button=>button.classList.toggle('on',button.dataset.route===(name==='scope-detail'?'scopes':['passages','factory','passage-editor'].includes(name)?'passages':name==='progress'?'students':name))); if(name==='scope-detail')renderScopeDetail();if(name==='factory')renderFactorySourceBuilder();if(name==='progress'&&!state.learning.data)loadLearningProgress();window.scrollTo({top:0,behavior:'instant'}); }
async function login(form) { const password=new FormData(form).get('password'); const data=await safely(()=>call('admin_login',{password},'','관리자 비밀번호를 확인하는 중…'),{auth:false}); form.reset(); if(!data)return; state.token=data.session.token; localStorage.setItem(SESSION_KEY,JSON.stringify(data.session)); await loadAdmin(); }
async function loadAdmin() { const data=await safely(()=>call('teacher_bootstrap',{},state.token,'관리자 화면을 불러오는 중…')); if(!data)return; state.data=data; $('#admin-login').hidden=true; $('#admin-nav').hidden=false; $('#admin-logout').hidden=false; renderStudents(); renderPassages(); renderScopes(); renderFactoryPassageOptions(); syncLearningFilterOptions(); route(state.route); }
async function logout() { if(state.token)await safely(()=>call('logout')); clearSession(); showLogin(); }
function renderFactoryPassageOptions(){const select=$('#factory-existing-passage');if(!select||!state.data)return;const current=select.value;select.innerHTML=`<option value="">Passage를 선택하세요</option>${state.data.passages.map(passage=>`<option value="${passage.id}" ${passage.has_workbook?'disabled':''}>${escapeHtml([passage.source_year,passage.source_month&&passage.source_month+'월',passage.title,passage.has_workbook&&`워크북 있음 (${passage.workbook_source})`].filter(Boolean).join(' · '))}</option>`).join('')}`;if([...select.options].some(option=>option.value===current&&!option.disabled))select.value=current;syncFactoryMode();}
const FACTORY_OPTIONS={grade:['1학년','2학년','3학년'],textbook:['공통영어1','공통영어2','영어I','영어II'],publisher:['동아(이병민)','YBM(박준언)','천재(강상구)','미래엔(김성연)'],lesson:['1과','2과','3과','4과','5과','6과','7과','8과'],year:[String(new Date().getFullYear()),String(new Date().getFullYear()-1),String(new Date().getFullYear()-2)],month:['3','6','9','11']};
function customFactoryOptions(key){try{return JSON.parse(localStorage.getItem(`ready-factory-${key}`)||'[]').filter(Boolean);}catch{return[];}}
function factoryOptions(key){return [...new Set([...(FACTORY_OPTIONS[key]||[]),...customFactoryOptions(key)])];}
function sourceChipGroup(key,label,values=factoryOptions(key)){const selected=state.factoryMeta[key];return `<section class="source-chip-row" data-source-chip-row="${key}"><span>${label}</span><div class="source-chips">${values.map(value=>`<button type="button" class="source-chip ${selected===value?'active':''}" data-source-chip="${key}" data-source-value="${escapeHtml(value)}">${escapeHtml(key==='month'?`${value}월`:value)}</button>`).join('')}<button type="button" class="source-chip add" data-add-source-chip="${key}" aria-label="${label} 추가">+</button><input class="source-chip-input" data-source-chip-input="${key}" aria-label="새 ${label}" placeholder="직접 입력" hidden></div></section>`;}
function renderFactorySourceBuilder(){const root=$('#factory-source-builder'),form=$('#factory-start-form');if(!root||!form)return;const meta=state.factoryMeta,isMock=meta.sourceType==='MOCK_EXAM';root.innerHTML=`<div class="source-kind" role="group" aria-label="Passage 종류"><button type="button" class="${!isMock?'active':''}" data-source-kind="TEXTBOOK">교과서</button><button type="button" class="${isMock?'active':''}" data-source-kind="MOCK_EXAM">모의고사</button></div><div class="source-fields">${sourceChipGroup('grade','학년')}${isMock?`${sourceChipGroup('year','연도')}${sourceChipGroup('month','월')}`:`${sourceChipGroup('textbook','교과서')}${sourceChipGroup('publisher','출판사')}${sourceChipGroup('lesson','Lesson')}`}</div><div class="generated-title"><span>자동 제목</span><strong>${escapeHtml(factoryTitle())}</strong></div>`;form.elements.sourceType.value=meta.sourceType;form.elements.grade.value=meta.grade;form.elements.sourceYear.value=isMock?meta.year:'';form.elements.sourceMonth.value=isMock?meta.month:'';form.elements.sourceLabel.value='';form.elements.title.value=factoryTitle();}
function factoryTitle(){const meta=state.factoryMeta;return meta.sourceType==='MOCK_EXAM'?`${meta.year}년 ${meta.month}월 ${meta.grade} 모의고사`:`${meta.textbook} ${meta.publisher} ${meta.lesson}`;}
function syncFactoryMode(){const form=$('#factory-start-form');if(!form)return;const existing=form.elements.factoryMode.value==='existing_passage',existingField=$('#factory-existing-field'),newFields=$('#factory-new-fields'),title=form.elements.title,passage=form.elements.existingPassageId;existingField.hidden=!existing;newFields.hidden=existing;title.required=!existing;passage.required=existing;$('#factory-pdf-note').textContent=existing?'선택 사항 · exercise/Answer Key 추출과 canonical 일치 검사에만 사용합니다.':'또는 아래에 본문을 붙여 넣으세요.';form.elements.sourceText.closest('label').hidden=existing;if(!existing)renderFactorySourceBuilder();}
function factoryCoverage(metrics){return [1,2,3,4,5,6,7].map(stage=>{const value=metrics?.stageCoverage?.[stage]||{};return `${stage}단계 ${Number(value.ready)||0}/${Number(value.expected)||0}`;}).join(' · ');}
function renderFactoryReview(result){const root=$('#factory-review');if(!root)return;const job=result?.job||state.factoryJob;if(!job)return;const changedJob=state.factoryJob?.id!==job.id;state.factoryJob=job;if(changedJob||!state.factoryRows.length)state.factoryRows=Array.isArray(job.extracted_rows)?job.extracted_rows.map(row=>({id:row.id||null,blockType:row.blockType||'SENTENCE',paragraphIndex:Number(row.paragraphIndex)||0,text:String(row.text||''),translation:String(row.translation||'')})):[];const extraction=job.extraction||{},existing=job.source_metadata?.factoryMode==='existing_passage';root.hidden=false;root.innerHTML=`<section class="card form-card"><p class="eyebrow">PASSAGE DRAFT</p><h2>${existing?'기존 Passage 확인':'Canonical Passage 확정'}</h2><p class="lead">${escapeHtml(extraction.reason||'구조와 문장쌍을 확인해 주세요.')} ${existing?'기존 Passage 편집은 Passage 상세에서 할 수 있습니다.':'저장 전까지 학생에게 공개되지 않습니다.'}</p><div class="table-wrap"><table><thead><tr><th>#</th><th>타입</th><th>English</th><th>Korean</th><th>문단</th><th></th></tr></thead><tbody>${state.factoryRows.map((row,index)=>`<tr><td>${index+1}</td><td><select data-factory-type="${index}" ${existing?'disabled':''}>${['SENTENCE','TITLE','SUBTITLE'].map(type=>`<option ${row.blockType===type?'selected':''}>${type}</option>`).join('')}</select></td><td><textarea data-factory-en="${index}" rows="3" ${existing?'readonly':''}>${escapeHtml(row.text)}</textarea></td><td><textarea data-factory-ko="${index}" rows="3" ${existing?'readonly':''}>${escapeHtml(row.translation)}</textarea></td><td><input data-factory-paragraph="${index}" type="number" min="0" value="${row.paragraphIndex}" ${existing?'readonly':''}></td><td>${existing?'':`<button class="button danger small" type="button" data-factory-delete="${index}">삭제</button><button class="button quiet small" type="button" data-factory-add-after="${index}">+ 아래</button>`}</td></tr>`).join('')}</tbody></table></div>${existing?'':'<button class="button quiet" type="button" data-factory-add-after="'+(state.factoryRows.length-1)+'">+ 행 추가</button>'}<section class="canonical-preview"><p class="eyebrow">STUDENT PREVIEW</p><div>${passagePreview(state.factoryRows)}</div></section><button class="button primary" type="button" data-factory-confirm>${existing?'워크북 검증':'Passage와 Workbook 검증'}</button></section>`;}
function captureFactoryRows(){if(state.factoryJob?.source_metadata?.factoryMode==='existing_passage')return;state.factoryRows=state.factoryRows.map((row,index)=>({...row,blockType:document.querySelector(`[data-factory-type="${index}"]`)?.value||row.blockType,paragraphIndex:Number(document.querySelector(`[data-factory-paragraph="${index}"]`)?.value)||0,text:document.querySelector(`[data-factory-en="${index}"]`)?.value?.trim()??row.text,translation:document.querySelector(`[data-factory-ko="${index}"]`)?.value?.trim()??row.translation}));}
function refreshCanonicalPreview(kind){if(kind==='factory')captureFactoryRows();else capturePassageRows();const rows=kind==='factory'?state.factoryRows:state.passageEditor?.rows||[],root=document.querySelector(kind==='factory'?'#factory-review .canonical-preview div':'#passage-editor .canonical-preview div');if(root)root.innerHTML=passagePreview(rows);}
function selectedFactoryPdf(form,data){const input=form.querySelector('input[type="file"][accept*="pdf"]'),direct=input?.files?.[0],fallback=data.get('pdf'),file=direct||fallback;return file&&typeof file==='object'&&Number(file.size)>0?file:null;}
async function startFactory(form){return importStudio(form);}
async function legacyStartFactory(form){const data=new FormData(form),values=Object.fromEntries(data),existing=values.factoryMode==='existing_passage',pdf=selectedFactoryPdf(form,data),sourceText=String(data.get('sourceText')||'').trim();delete values.pdf;if(existing&&!values.existingPassageId)return toast('기존 Passage를 선택해 주세요.');if(!pdf){if(!existing&&!sourceText)return toast('PDF 또는 본문을 입력해 주세요.');const result=await safely(()=>call('factory_start',{...values,sourceKind:'text',sourceText},state.token,existing?'기존 Passage를 확인하는 중…':'본문을 분석하는 중…'));if(result)renderFactoryReview(result);return;}if(pdf.size>7_000_000)return toast('PDF는 7MB 이하로 올려 주세요.');const pdfBase64=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=()=>reject(new Error('PDF를 읽을 수 없습니다.'));reader.onload=()=>resolve(String(reader.result||''));reader.readAsDataURL(pdf);});const result=await safely(()=>call('factory_start',{...values,sourceKind:'pdf',pdfBase64,documentName:pdf.name},state.token,'PDF를 분석하는 중…'));if(result)renderFactoryReview(result);}
async function confirmFactory({finalize=false,allowIncomplete=false}={}){if(!state.factoryJob)return;const existing=state.factoryJob.source_metadata?.factoryMode==='existing_passage';if(!finalize)captureFactoryRows();const payload={jobId:state.factoryJob.id,finalize,allowIncomplete,...(!finalize&&!existing?{sentenceRows:state.factoryRows}:{})};const result=await safely(()=>call('factory_confirm',payload,state.token,finalize?'Passage와 워크북을 최종 저장하는 중…':'워크북을 생성하고 검증하는 중…'));if(!result)return;if(finalize&&result.incompleteReview){$('#factory-review').innerHTML=`<section class="card form-card"><div class="result bad"><strong>최종 저장 전 검증 결과가 달라졌습니다.</strong><p>${escapeHtml(factoryCoverage(result.metrics))}</p><p>Passage와 워크북은 아직 저장되지 않았습니다. 누락을 인정하고 저장하려면 아래 버튼을 눌러 주세요.</p></div><button class="button danger" type="button" data-factory-finalize-incomplete>누락을 인정하고 최종 확정</button></section>`;return;}if(!finalize&&result.confirmationRequired){const incomplete=result.incompleteReview===true;$('#factory-review').innerHTML=`<section class="card form-card"><div class="result ${incomplete?'bad':'good'}"><strong>${incomplete?'단계별 문제 수를 확인해 주세요.':'검증 완료'}</strong><p>${escapeHtml(factoryCoverage(result.metrics))}</p><p>${incomplete?'누락된 exercise는 학생에게 공개되지 않습니다. 아래 버튼을 누르면 이 상태를 인정하고 Passage와 워크북을 저장합니다.':'모든 필수 단계가 검증되었습니다. 아래 버튼을 눌러야 Passage와 워크북이 실제로 저장됩니다.'}</p></div><button class="button ${incomplete?'danger':'primary'}" type="button" ${incomplete?'data-factory-finalize-incomplete':'data-factory-finalize'}>${incomplete?'누락을 인정하고 최종 확정':'최종 확정'}</button></section>`;return;}state.factoryJob={...state.factoryJob,status:'ready'};$('#factory-review').innerHTML=`<div class="card result good"><strong>Workbook ready</strong><p>${escapeHtml(factoryCoverage(result.metrics))}</p><p>문장 ${result.metrics?.sentenceCount||0} · deterministic ${result.metrics?.deterministicGeneratedExercises||0} · Gemini ${result.metrics?.geminiGeneratedExercises||0} · validator DROP ${result.metrics?.validatorDrop||0}</p></div>`;await loadAdmin();toast(existing?'기존 Passage는 그대로 두고 워크북만 저장했습니다.':'최종 확정되어 Passage와 READY 워크북을 저장했습니다.');}
async function regenerateFactoryWorkbook(passageId){const passage=state.data?.passages.find(item=>item.id===passageId);if(!passage||passage.workbook_source!=='factory')return;if(!confirm(`“${passage.title}” 워크북을 최신 Factory 규칙으로 다시 생성할까요?\n기존 Passage와 연결 데이터는 변경되지 않습니다.`))return;const result=await safely(()=>call('factory_regenerate',{passageId},state.token,'기존 워크북을 최신 규칙으로 재생성하는 중…'));if(!result)return;if(result.incompleteReview){toast(`재생성 중단 · ${factoryCoverage(result.metrics)}`);return;}await loadAdmin();toast(`워크북 재생성 완료 · ${factoryCoverage(result.metrics)}`);}
async function regenerateDeterministic(passageId,{quiet=false}={}){const result=await safely(()=>call('regenerate_passage_deterministic',{passageId},state.token,'Deterministic Workbook을 생성하는 중…'));if(!result)return null;if(!quiet){await loadAdmin();toast('Deterministic Workbook을 최신화했습니다.');}return result;}
async function regenerateAllDeterministic(){const targets=[...(state.data?.passages||[])],root=$('#deterministic-progress');if(!targets.length)return;root.hidden=false;let success=0,failed=0;const failures=[];for(let index=0;index<targets.length;index++){root.innerHTML=`<div class="card compact-card"><strong>Deterministic regeneration ${index+1} / ${targets.length}</strong><p>✓ ${success} updated · ⚠ ${failed} kept previous</p></div>`;const result=await regenerateDeterministic(targets[index].id,{quiet:true});if(result)success+=1;else{failed+=1;failures.push(targets[index].title);}}await loadAdmin();const fresh=$('#deterministic-progress');fresh.hidden=false;fresh.innerHTML=`<div class="card compact-card ${failed?'result bad':'result good'}"><strong>${targets.length}개 완료</strong><p>✓ ${success} updated · ⚠ ${failed} kept previous</p>${failures.length?`<small>${failures.map(escapeHtml).join(' · ')}</small>`:''}</div>`;}
function passagesForExam(examId){const byId=new Map(state.data.passages.map(passage=>[passage.id,passage]));return state.data.examPassages.filter(link=>link.exam_id===examId).sort((a,b)=>a.position-b.position).map(link=>{const passage=byId.get(link.passage_id);return passage?{...passage,scope_position:link.position,group_key:link.group_key,group_label:link.group_label}:null;}).filter(Boolean);}

function syncLearningFilterOptions(){if(!state.data)return;const schools=[...new Set(state.data.students.map(student=>student.school))].sort((a,b)=>a.localeCompare(b,'ko')),grades=[...new Set(state.data.students.map(student=>student.grade))].sort((a,b)=>a.localeCompare(b,'ko'));const school=$('#learning-school-filter'),grade=$('#learning-grade-filter');if(school)school.innerHTML=`<option value="">전체 학교</option>${schools.map(value=>`<option ${state.learning.school===value?'selected':''}>${escapeHtml(value)}</option>`).join('')}`;if(grade)grade.innerHTML=`<option value="">전체 학년</option>${grades.map(value=>`<option ${state.learning.grade===value?'selected':''}>${escapeHtml(value)}</option>`).join('')}`;}
function relativeActivity(value){if(!value)return'학습 기록 없음';const elapsed=Math.max(0,Date.now()-Date.parse(value)),minute=60_000,hour=60*minute,day=24*hour;if(elapsed<minute)return'방금';if(elapsed<hour)return`${Math.floor(elapsed/minute)}분 전`;if(elapsed<day)return`${Math.floor(elapsed/hour)}시간 전`;if(elapsed<2*day)return'어제';return`${Math.floor(elapsed/day)}일 전`;}
function accuracyHtml(metrics){const accuracy=progressAccuracy(metrics?.correct,metrics?.total);return accuracy==null?'—':`${accuracy}%`;}
async function loadLearningProgress(){const learning=state.learning,data=await safely(()=>call('admin_workbook_progress',{period:learning.period,school:learning.school,grade:learning.grade},state.token,'학습 현황을 계산하는 중…'));if(!data)return;learning.data=data;learning.detail=null;learning.replay=null;renderLearningProgress();}
function renderLearningProgress(){const root=$('#learning-progress-summary'),detail=$('#learning-progress-detail');if(!root||!state.learning.data)return;if(detail)detail.hidden=true;root.hidden=false;const learning=state.learning,rows=[...(learning.data.students||[])].sort((a,b)=>{const left=a.lastActivityAt?Date.parse(a.lastActivityAt):0,right=b.lastActivityAt?Date.parse(b.lastActivityAt):0;return learning.sort==='recent'?right-left:left-right;});$$('[data-learning-period]').forEach(button=>button.classList.toggle('active',button.dataset.learningPeriod===learning.period));const sort=$('#learning-sort');if(sort)sort.value=learning.sort;root.innerHTML=rows.length?`<div class="table-wrap learning-table"><table><thead><tr><th>학생</th><th>마지막 학습</th><th>워크북</th><th>워크북 정답률</th><th>워크북 오답</th></tr></thead><tbody>${rows.map(student=>`<tr tabindex="0" role="button" data-open-learning-student="${student.id}" aria-label="${escapeHtml(student.name)} 학습 상세"><td><strong>${escapeHtml(student.name)}</strong><small>${escapeHtml(student.school)} · ${escapeHtml(student.grade)}</small></td><td>${escapeHtml(relativeActivity(student.lastActivityAt))}</td><td>${student.workbook.total}</td><td>${accuracyHtml(student.workbook)}</td><td>${student.workbook.wrong}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">조건에 맞는 학생이 없습니다.</div>';}
function attemptWhen(value){return new Intl.DateTimeFormat('ko-KR',{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit',hour12:false,timeZone:'Asia/Seoul'}).format(new Date(value));}
function workbookGroupHtml(items){const byItem=new Map();for(const item of items){const key=`${item.passageTitle}:${item.stage}:${item.itemKey}`,list=byItem.get(key)||[];list.push(item);byItem.set(key,list);}return [...byItem.values()].map((attempts,index)=>{const item=attempts[0];return `<details class="learning-wrong-group" ${index===0?'open':''}><summary><span><strong>${escapeHtml(item.passageTitle)}</strong><small>Stage ${item.stage}${item.kind?` · ${escapeHtml(item.kind)}`:''}${item.number?` · ${escapeHtml(item.number)}`:''}</small></span><b>${item.attemptCount}회 시도 / ${item.wrongCount}회 오답</b></summary><div>${attempts.map((attempt,attemptIndex)=>`<button type="button" data-open-learning-attempt="${attempt.id}" data-learning-attempt-kind="workbook"><span>오답 시도 ${attemptIndex+1}</span><small>${escapeHtml(attemptWhen(attempt.createdAt))}${attempt.replayAvailable?'':' · 현재 catalog 불일치'}</small><b>보기 →</b></button>`).join('')}</div></details>`;}).join('');}
async function openLearningStudent(studentId){if(!state.learning.data)await loadLearningProgress();route('progress');const data=await safely(()=>call('admin_workbook_progress_detail',{studentId,period:state.learning.period},state.token,'학생 학습 기록을 불러오는 중…'));if(!data)return;state.learning.detail=data;state.learning.replay=null;renderLearningDetail();}
function renderLearningDetail(){const data=state.learning.detail,summary=$('#learning-progress-summary'),root=$('#learning-progress-detail');if(!data||!root)return;summary.hidden=true;root.hidden=false;root.innerHTML=`<div class="learning-detail-head"><button class="back-link" type="button" data-close-learning-student>← 학생별 현황</button><div><p class="eyebrow">STUDENT · ${escapeHtml(state.learning.period==='today'?'오늘':state.learning.period==='30d'?'최근 30일':'최근 7일')}</p><h1>${escapeHtml(data.student.name)}</h1><p>${escapeHtml(data.student.school)} · ${escapeHtml(data.student.grade)}</p></div><div class="learning-detail-metrics"><span><strong>Workbook ${data.workbook.total}개</strong>${accuracyHtml(data.workbook)}</span><span><strong>마지막 학습</strong>${escapeHtml(relativeActivity(state.learning.data?.students?.find(student=>student.id===data.student.id)?.lastActivityAt))}</span></div></div><div id="learning-attempt-replay" hidden></div>${!data.workbook.total?'<div class="empty learning-empty">선택한 기간에 학습 기록이 없습니다.</div>':`<div class="learning-wrong-layout"><section><header><h2>틀린 Workbook</h2><small>오답 attempt ${data.wrongWorkbooks.length}회</small></header>${data.wrongWorkbooks.length?workbookGroupHtml(data.wrongWorkbooks):'<div class="empty compact-empty">틀린 Workbook이 없습니다.</div>'}</section></div>`}`;}
async function openLearningAttempt(attemptId){const data=await safely(()=>call('admin_workbook_attempt_replay',{attemptId},state.token,'제출 화면을 재현하는 중…'));if(!data)return;state.learning.replay=data;const root=$('#learning-attempt-replay');if(!root)return;root.hidden=false;root.innerHTML=`<div class="learning-replay-toolbar"><button class="back-link" type="button" data-close-learning-attempt>← 오답 목록</button><span>${escapeHtml(attemptWhen(data.attempt?.created_at))}</span></div>${workbookAttemptReplayHtml(data,escapeHtml)}`;root.scrollIntoView({behavior:'smooth',block:'start'});}

function renderStudents() {
  const school=$('#student-school-filter')?.value||'',grade=$('#student-grade-filter')?.value||'';
  const students=state.data.students.filter(student=>(!school||student.school===school)&&(!grade||student.grade===grade));
  const root=$('#admin-students');
  root.innerHTML=students.length?`<div class="table-wrap student-table"><table><thead><tr><th>이름</th><th>학교 / 학년</th><th>학생 코드 변경</th><th></th></tr></thead><tbody>${students.map(student=>`<tr><td><button type="button" class="text-button" data-open-learning-student="${student.id}">${escapeHtml(student.name)}</button></td><td>${escapeHtml(student.school)} · ${escapeHtml(student.grade)}</td><td><form class="pin-reset" data-reset-code="${student.id}"><input name="code" type="password" inputmode="numeric" pattern="[0-9]{6}" minlength="6" maxlength="6" autocomplete="new-password" placeholder="새 6자리 코드" required><button class="button quiet small" type="submit">변경</button></form></td><td><button class="button quiet small" type="button" data-edit-student="${student.id}">정보 수정</button><button class="button danger small" type="button" data-delete-student="${student.id}">삭제</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">조건에 맞는 학생이 없습니다.</div>';
}
function renderPassageSelection(){
  const root=$('#passage-selection'), selected=state.data.passages.filter(p=>state.selectedPassageIds.has(p.id)); if(!root)return;
  if(!selected.length){root.innerHTML='';return;}
  const grades=[...new Set(selected.map(p=>p.grade))], mixed=grades.length!==1;
  root.innerHTML=`<section class="card passage-selection"><div class="selection-summary"><strong>${selected.length}개 지문 선택</strong><button class="button quiet small" type="button" data-clear-passage-selection>선택 해제</button></div>${mixed?'<div class="result bad">같은 학년 지문만 하나의 시험범위에 배정할 수 있습니다.</div>':`<form id="assign-passages-to-scope" class="form-grid scope-assign"><label><span>학교</span><select name="school" required>${SCOPE_SLOTS.filter(([,grade])=>grade===grades[0]).map(([school])=>`<option>${school}</option>`).join('')}</select></label><label><span>학년</span><input name="grade" value="${escapeHtml(grades[0])}" readonly></label><button class="button primary" type="submit">선택한 지문 배정</button></form>`}</section>`;
}
function deterministicState(p){return p.deterministic_status==='current'&&Number(p.deterministic_catalog_revision)===Number(p.canonical_revision)?'✓ 최신':p.deterministic_status==='failed'?'⚠ 생성 실패':'⚠ 재생성 필요';}
function renderPassages(){const root=$('#passage-library');if(!root)return;const validIds=new Set(state.data.passages.map(p=>p.id));state.selectedPassageIds=new Set([...state.selectedPassageIds].filter(id=>validIds.has(id)));const grade=$('#passage-grade-filter')?.value||'',type=$('#passage-type-filter')?.value||'',year=$('#passage-year-filter')?.value||'',month=$('#passage-month-filter')?.value||'';const rows=state.data.passages.filter(p=>(!grade||p.grade===grade)&&(!type||p.source_type===type)&&(!year||String(p.source_year)===year)&&(!month||String(p.source_month)===month));const pageSize=15,totalPages=Math.max(1,Math.ceil(rows.length/pageSize));state.passagePage=Math.min(state.passagePage,totalPages-1);const page=rows.slice(state.passagePage*pageSize,(state.passagePage+1)*pageSize);root.innerHTML=`<div class="library-note"><span>지문을 체크해 시험범위에 배정하세요.</span><button class="button quiet small" type="button" data-regenerate-all>모든 지문 Deterministic 다시 생성</button></div><div id="deterministic-progress" hidden></div><div class="table-wrap"><table><thead><tr><th>선택</th><th>제목</th><th>종류</th><th>학년</th><th>상태</th><th></th></tr></thead><tbody>${page.map(p=>`<tr data-passage-row="${p.id}"><td><input class="passage-check" type="checkbox" aria-label="${escapeHtml(p.title)} 선택" data-select-passage="${p.id}" ${state.selectedPassageIds.has(p.id)?'checked':''}></td><td><button class="text-button" type="button" data-edit-passage="${p.id}">${escapeHtml(p.title)}</button><small>${escapeHtml(p.source_type==='MOCK_EXAM'?[p.source_year,p.source_month&&p.source_month+'월'].filter(Boolean).join(' · '):p.grade)}</small></td><td>${p.source_type==='MOCK_EXAM'?'모의고사':'교과서'}</td><td>${escapeHtml(p.grade)}</td><td><span class="pipeline-state">${p.studio_state?(p.studio_state.needsReview?'Authoring 필요':p.studio_state.published?'발행 완료':'발행 가능'):'발행 완료'}</span></td><td><button class="button quiet small" type="button" data-regenerate-deterministic="${p.id}">Deterministic 다시 생성</button><button class="button quiet small" type="button" data-edit-passage="${p.id}">편집</button><button class="button danger small" type="button" data-delete-passage="${p.id}">삭제</button></td></tr>`).join('')||'<tr><td colspan="6">조건에 맞는 지문이 없습니다.</td></tr>'}</tbody></table></div><div class="pagination"><button class="button quiet small" type="button" data-passage-page="prev" ${state.passagePage===0?'disabled':''}>← 이전</button><span>${state.passagePage+1} / ${totalPages}</span><button class="button quiet small" type="button" data-passage-page="next" ${state.passagePage===totalPages-1?'disabled':''}>다음 →</button></div>`;renderPassageSelection();}
function capturePassageRows(){if(!state.passageEditor)return;state.passageEditor.rows=state.passageEditor.rows.map((row,index)=>({...row,blockType:document.querySelector(`[data-canonical-type="${index}"]`)?.value||row.blockType,text:document.querySelector(`[data-canonical-en="${index}"]`)?.value??row.text,translation:document.querySelector(`[data-canonical-ko="${index}"]`)?.value??row.translation}));}
function passagePreview(rows){let paragraph=-1,html='';for(const row of rows){if(row.blockType==='TITLE')html+=`<h2>${escapeHtml(row.text||'Title')}</h2>`;else if(row.blockType==='SUBTITLE')html+=`<h3>${escapeHtml(row.text||'Subtitle')}</h3>`;else{if(Number(row.paragraphIndex)!==paragraph){paragraph=Number(row.paragraphIndex);html+='<br>';}html+=` <span>${escapeHtml(row.text||'English sentence')}</span>`;}}return html;}
function canonicalKindLabel(type){return type==='TITLE'?'제목':type==='SUBTITLE'?'부제목':'본문';}
function renderPassageEditor(){const data=state.passageEditor;if(!data)return;const p=data.passage,rows=data.rows;$('#passage-page-title').textContent=p.title;$('#passage-editor').innerHTML=`<form id="update-passage-form"><section class="passage-meta-editor"><label class="passage-title-field"><span>제목</span><input name="title" value="${escapeHtml(p.title)}" required></label><label><span>종류</span><select name="sourceType"><option value="TEXTBOOK" ${p.source_type==='TEXTBOOK'?'selected':''}>교과서</option><option value="MOCK_EXAM" ${p.source_type==='MOCK_EXAM'?'selected':''}>모의고사</option></select></label><label><span>학년</span><select name="grade">${['1학년','2학년','3학년'].map(value=>`<option ${p.grade===value?'selected':''}>${value}</option>`).join('')}</select></label><label><span>연도</span><input name="sourceYear" inputmode="numeric" value="${p.source_year||''}"></label><label><span>월</span><input name="sourceMonth" inputmode="numeric" value="${p.source_month||''}"></label><input name="sourceLabel" type="hidden" value=""></section><p class="editor-hint">영문과 해석을 문장별로 다듬으세요.</p>${p.deterministic_error?`<p class="result bad">${escapeHtml(p.deterministic_error)}</p>`:''}<div class="canonical-editor">${rows.map((row,index)=>`<article class="canonical-row"><div class="canonical-rail"><span>${String(index+1).padStart(2,'0')}</span><button type="button" data-canonical-delete="${index}" ${rows.length===1?'disabled':''} aria-label="${index+1}번 행 삭제">−</button><button type="button" data-canonical-add="${index}" aria-label="${index+1}번 행 아래 추가">+</button></div><div class="canonical-copy"><button class="canonical-kind" type="button" data-canonical-kind="${index}">${canonicalKindLabel(row.blockType)}</button><input type="hidden" data-canonical-type="${index}" value="${row.blockType}"><textarea data-canonical-en="${index}" rows="2" aria-label="${index+1}번 영문" placeholder="English sentence">${escapeHtml(row.text)}</textarea></div><div class="canonical-copy korean-copy"><div class="canonical-copy-head"><span>해석</span><button class="easy-translation" type="button" data-easy-translation="${index}" ${row.id?'':'disabled'}>AI로 쉽게</button></div><textarea data-canonical-ko="${index}" rows="2" aria-label="${index+1}번 해석" placeholder="한국어 해석">${escapeHtml(row.translation)}</textarea></div></article>`).join('')}</div><section class="canonical-preview"><p class="eyebrow">PASSAGE PREVIEW</p><h1>${escapeHtml(p.title)}</h1><div>${passagePreview(rows)}</div></section><div class="canonical-footer"><button class="button quiet" type="button" data-regenerate-deterministic="${p.id}">Deterministic 다시 생성</button><button class="button primary" type="submit">Passage 저장</button></div></form>`;}
async function openPassage(passageId){state.passageEditorId=passageId;route('passage-editor');$('#passage-editor').innerHTML='<div class="empty">Passage를 불러오는 중입니다.</div>';const data=await safely(()=>call('studio_open',{passageId},state.token,'Passage를 불러오는 중…'));if(!data)return closePassage();state.passageEditor=data;renderPassageEditor();await attachStudio(passageId,data);}
function closePassage(){state.passageEditorId=null;state.passageEditor=null;document.querySelector('#studio-authoring')?.remove();document.querySelector('.studio-flow')?.remove();route('passages');}

function renderScopes() {
  const root=$('#teacher-exams');
  const schools=[...new Set(SCOPE_SLOTS.map(([school])=>school))];
  root.innerHTML=schools.map(school=>`<section class="scope-school"><h2>${escapeHtml(school)}${school.startsWith('test')?' · QA 전용':''}</h2><div class="scope-grid">${SCOPE_SLOTS.filter(([slotSchool])=>slotSchool===school).map(([,grade])=>{const scope=state.data.exams.find(item=>item.school===school&&item.grade===grade),passages=scope?passagesForExam(scope.id):[];return `<button class="card scope-card scope-card-button" type="button" data-open-scope-school="${escapeHtml(school)}" data-open-scope-grade="${escapeHtml(grade)}"><div class="card-head"><div><p class="eyebrow">${school.startsWith('test')?'PRIVATE QA SCOPE':'CURRENT SCOPE'}</p><h3>${escapeHtml(grade)}</h3><p class="lead compact">지문 ${passages.length}개</p></div><span class="scope-card-arrow" aria-hidden="true">→</span></div><div class="passage-list">${passages.slice(0,4).map((p,index)=>`<div class="recent-row"><span>${index+1}. ${escapeHtml(p.title)}</span></div>`).join('')||'<div class="empty compact-empty">아직 배정된 지문이 없습니다.</div>'}${passages.length>4?`<p class="lead compact">외 ${passages.length-4}개</p>`:''}</div><span class="scope-card-cta">눌러서 묶음·순서 편집</span></button>`;}).join('')}</div></section>`).join('');
}
function scopePassageRow(passageId,groupKey,index){const passage=state.data.passages.find(item=>item.id===passageId);if(!passage)return'';const options=[['','묶음 없음'],...state.scopeEditor.layout.groups.map(group=>[group.key,group.label])],list=groupKey?state.scopeEditor.layout.groups.find(group=>group.key===groupKey)?.passageIds:state.scopeEditor.layout.ungrouped;return `<div class="scope-layout-passage" draggable="true" data-scope-passage="${passage.id}" data-scope-group="${escapeHtml(groupKey)}"><span class="drag-handle" aria-hidden="true">≡</span><span class="scope-layout-passage-copy"><strong>${escapeHtml(passage.title)}</strong><small>${passage.source_type==='MOCK_EXAM'?'모의고사':'교과서'} · ${escapeHtml(passage.grade)}</small></span><select data-move-scope-passage="${passage.id}" aria-label="${escapeHtml(passage.title)} 묶음 이동">${options.map(([key,label])=>`<option value="${escapeHtml(key)}" ${key===groupKey?'selected':''}>${escapeHtml(label)}</option>`).join('')}</select><span class="scope-order-buttons"><button type="button" class="icon-button" data-move-passage-up="${passage.id}" aria-label="위로 이동" ${index===0?'disabled':''}>↑</button><button type="button" class="icon-button" data-move-passage-down="${passage.id}" aria-label="아래로 이동" ${index===list.length-1?'disabled':''}>↓</button></span></div>`;}
function scopeGroup(group,index){const collapsed=state.scopeEditor.collapsedGroups?.has(group.key);return `<section class="scope-layout-group ${collapsed?'is-collapsed':''}" draggable="true" data-scope-group-card="${escapeHtml(group.key)}"><header><span class="drag-handle" aria-hidden="true">≡</span><input value="${escapeHtml(group.label)}" maxlength="120" aria-label="묶음 이름" data-scope-group-label="${escapeHtml(group.key)}" required><button type="button" class="button quiet small scope-collapse" data-toggle-scope-group="${escapeHtml(group.key)}" aria-expanded="${collapsed?'false':'true'}">${collapsed?'펼치기':'접기'}</button><span class="scope-order-buttons"><button type="button" class="icon-button" data-move-group-up="${escapeHtml(group.key)}" aria-label="묶음 위로 이동" ${index===0?'disabled':''}>↑</button><button type="button" class="icon-button" data-move-group-down="${escapeHtml(group.key)}" aria-label="묶음 아래로 이동" ${index===state.scopeEditor.layout.groups.length-1?'disabled':''}>↓</button></span><button type="button" class="button danger small" data-delete-scope-group="${escapeHtml(group.key)}">묶음 삭제</button></header><div class="scope-layout-list" data-scope-dropzone="${escapeHtml(group.key)}" ${collapsed?'hidden':''}>${group.passageIds.map((id,passageIndex)=>scopePassageRow(id,group.key,passageIndex)).join('')||'<p class="scope-layout-empty">Passage를 이곳으로 옮기세요.</p>'}</div></section>`;}
function renderScopeDetail(){
  const root=$('#scope-detail-content'), editor=state.scopeEditor;if(!root||!editor||!state.data)return;
  const scope=state.data.exams.find(item=>item.school===editor.school&&item.grade===editor.grade),available=state.data.passages.filter(p=>p.grade===editor.grade);if(!scope)return;
  if(!editor.layout)editor.layout=createScopeLayout(state.data.examPassages.filter(link=>link.exam_id===scope.id),scope.empty_passage_groups||[]);
  if(!editor.collapsedGroups)editor.collapsedGroups=new Set();
  const included=new Set(passageIds(editor.layout));
  root.innerHTML=`<div class="page-head scope-detail-head"><div><button class="back-link" type="button" data-close-scope-detail><span aria-hidden="true">‹</span> 시험범위</button><p class="eyebrow">${editor.school.startsWith('test')?'PRIVATE QA SCOPE':'CURRENT SCOPE'}</p><h1>${escapeHtml(editor.school)} · ${escapeHtml(editor.grade)}</h1><p class="lead">체크로 여러 지문을 한 번에 추가·제외한 뒤 한 번만 저장하세요.</p></div></div><form data-set-scope-layout class="scope-detail-form"><section class="scope-membership"><header><div><strong>지문 선택</strong><small>${included.size} / ${available.length}개 포함</small></div><div><button class="button quiet small" type="button" data-scope-select-all>전체 선택</button><button class="button quiet small" type="button" data-scope-select-none>전체 제외</button></div></header><div class="scope-passage-grid">${available.map(p=>`<label class="scope-passage-row"><input type="checkbox" data-scope-toggle-passage="${p.id}" ${included.has(p.id)?'checked':''}><span><strong>${escapeHtml(p.title)}</strong><small>${p.source_type==='MOCK_EXAM'?'모의고사':'교과서'} · ${escapeHtml(p.grade)}</small></span></label>`).join('')||'<div class="empty">이 학년에 등록된 Passage가 없습니다.</div>'}</div></section><div class="scope-detail-toolbar"><strong>${included.size}개 Passage · ${editor.layout.groups.length}개 묶음</strong><div class="scope-actions"><button class="button quiet" type="button" data-add-scope-group>+ 묶음 추가</button><button class="button primary" type="submit">변경사항 저장</button></div></div><div class="scope-layout">${editor.layout.groups.map(scopeGroup).join('')}<section class="scope-layout-group scope-layout-ungrouped"><header><div><strong>묶음 없음</strong><small>개별 Passage로 표시됩니다.</small></div></header><div class="scope-layout-list" data-scope-dropzone="">${editor.layout.ungrouped.map((id,index)=>scopePassageRow(id,UNGROUPED,index)).join('')||'<p class="scope-layout-empty">묶음 없는 Passage가 없습니다.</p>'}</div></section></div><div class="scope-detail-footer"><button class="button quiet" type="button" data-close-scope-detail>취소</button><button class="button primary" type="submit">변경사항 저장</button></div></form>`;
}
const impactLabels={sentences:'문장',questions:'연결 학습자료',examLinks:'시험범위 연결',passageLinks:'포함 지문',attempts:'풀이 기록',savedWords:'저장 단어·표현',savedSentences:'저장 문장',wordLookups:'단어 조회 기록',translationViews:'해석 조회 기록'};
async function openDelete(targetType,targetId){
  const impact=await safely(()=>call('delete_impact',{targetType,targetId},state.token,'삭제 영향을 확인하는 중…'));if(!impact)return;state.deleteTarget={targetType,targetId,impact};
  const typeLabel={student:'학생',passage:'지문'}[targetType],counts=Object.entries(impact.counts).filter(([,count])=>count>0);
  $('#delete-title').textContent=`${impact.label}을 삭제할까요?`;
  $('#delete-content').innerHTML=`<p class="lead">${typeLabel}과 연결된 READY 학습 기록도 함께 삭제됩니다. 삭제한 데이터는 되돌릴 수 없습니다.</p>${counts.length?`<ul class="impact-list">${counts.map(([kind,count])=>`<li><span>${escapeHtml(impactLabels[kind]||kind)}</span><strong>${count}건</strong></li>`).join('')}</ul>`:'<p class="lead">연결 데이터가 없습니다.</p>'}<form id="delete-form" class="delete-actions"><button class="button quiet" type="button" data-close-delete>취소</button><button class="button danger" type="submit">삭제</button></form>`;
  $('#delete-modal').classList.add('on');$('#delete-modal').setAttribute('aria-hidden','false');
}
function closeDelete(){$('#delete-modal').classList.remove('on');$('#delete-modal').setAttribute('aria-hidden','true');state.deleteTarget=null;}
document.addEventListener('input',event=>{if(event.target.matches?.('[data-canonical-en],[data-canonical-ko]'))refreshCanonicalPreview('passage');if(event.target.matches?.('[data-factory-en],[data-factory-ko],[data-factory-paragraph]'))refreshCanonicalPreview('factory');if(event.target.matches?.('#update-passage-form [name="title"]')){const title=document.querySelector('#passage-editor .canonical-preview h1');if(title)title.textContent=event.target.value;$('#passage-page-title').textContent=event.target.value;}});
document.addEventListener('change',event=>{if(event.target.matches?.('[data-factory-type]'))refreshCanonicalPreview('factory');});
document.addEventListener('change',event=>{if(event.target.id==='factory-mode')syncFactoryMode();if(event.target.name==='school'&&event.target.closest('#create-student-form')&&['test','test2'].includes(event.target.value))event.target.form.elements.grade.value=event.target.value==='test'?'1학년':'2학년';if(event.target.id==='student-school-filter'||event.target.id==='student-grade-filter')renderStudents();if(event.target.dataset.selectPassage){if(event.target.checked)state.selectedPassageIds.add(event.target.dataset.selectPassage);else state.selectedPassageIds.delete(event.target.dataset.selectPassage);renderPassageSelection();}});
function saveFactoryChip(input){const key=input.dataset.sourceChipInput,value=input.value.trim();if(!value)return;const custom=customFactoryOptions(key);if(!custom.includes(value))localStorage.setItem(`ready-factory-${key}`,JSON.stringify([...custom,value]));state.factoryMeta[key]=value;renderFactorySourceBuilder();}
document.addEventListener('click',event=>{const button=event.target.closest('button');if(button?.dataset.sourceKind){state.factoryMeta.sourceType=button.dataset.sourceKind;return renderFactorySourceBuilder();}if(button?.dataset.sourceChip){state.factoryMeta[button.dataset.sourceChip]=button.dataset.sourceValue;return renderFactorySourceBuilder();}if(button?.dataset.addSourceChip){const input=document.querySelector(`[data-source-chip-input="${button.dataset.addSourceChip}"]`);input.hidden=false;input.focus();return;}});
document.addEventListener('keydown',event=>{if(event.target.dataset.sourceChipInput&&event.key==='Enter'){event.preventDefault();saveFactoryChip(event.target);}});
document.addEventListener('change',event=>{if(['passage-grade-filter','passage-type-filter','passage-year-filter','passage-month-filter'].includes(event.target.id)){state.passagePage=0;renderPassages();}});
document.addEventListener('change',event=>{if(event.target.id==='learning-school-filter'){state.learning.school=event.target.value;state.learning.data=null;loadLearningProgress();}if(event.target.id==='learning-grade-filter'){state.learning.grade=event.target.value;state.learning.data=null;loadLearningProgress();}if(event.target.id==='learning-sort'){state.learning.sort=event.target.value==='recent'?'recent':'oldest';renderLearningProgress();}});
document.addEventListener('input',event=>{const key=event.target.dataset.scopeGroupLabel;if(key===undefined||!state.scopeEditor?.layout)return;const group=state.scopeEditor.layout.groups.find(item=>item.key===key);if(group)group.label=event.target.value;});
document.addEventListener('change',event=>{if(!state.scopeEditor?.layout)return;const toggleId=event.target.dataset.scopeTogglePassage;if(toggleId){if(event.target.checked)movePassage(state.scopeEditor.layout,toggleId,UNGROUPED);else removePassage(state.scopeEditor.layout,toggleId);return renderScopeDetail();}const passageId=event.target.dataset.moveScopePassage;if(passageId!==undefined){movePassage(state.scopeEditor.layout,passageId,event.target.value||UNGROUPED);renderScopeDetail();}});
document.addEventListener('click',event=>{const button=event.target.closest('button');const layout=state.scopeEditor?.layout;if(!button||!layout)return;if(button.hasAttribute('data-scope-select-all')){state.data.passages.filter(p=>p.grade===state.scopeEditor.grade).forEach(p=>movePassage(layout,p.id,UNGROUPED));return renderScopeDetail();}if(button.hasAttribute('data-scope-select-none')){[...passageIds(layout)].forEach(id=>removePassage(layout,id));return renderScopeDetail();}if(button.hasAttribute('data-add-scope-group')){addGroup(layout);return renderScopeDetail();}if(button.dataset.toggleScopeGroup!==undefined){const collapsed=state.scopeEditor.collapsedGroups||(state.scopeEditor.collapsedGroups=new Set());if(collapsed.has(button.dataset.toggleScopeGroup))collapsed.delete(button.dataset.toggleScopeGroup);else collapsed.add(button.dataset.toggleScopeGroup);return renderScopeDetail();}if(button.dataset.deleteScopeGroup!==undefined){removeGroup(layout,button.dataset.deleteScopeGroup);return renderScopeDetail();}if(button.dataset.moveGroupUp!==undefined||button.dataset.moveGroupDown!==undefined){const key=button.dataset.moveGroupUp??button.dataset.moveGroupDown,index=layout.groups.findIndex(group=>group.key===key),delta=button.dataset.moveGroupUp!==undefined?-1:2;moveGroup(layout,key,index+delta);return renderScopeDetail();}const passageId=button.dataset.movePassageUp??button.dataset.movePassageDown;if(passageId!==undefined){const row=button.closest('[data-scope-passage]'),groupKey=row?.dataset.scopeGroup||UNGROUPED,list=groupKey?layout.groups.find(group=>group.key===groupKey)?.passageIds:layout.ungrouped,index=list?.indexOf(passageId)??-1;if(index>=0)movePassage(layout,passageId,groupKey,index+(button.dataset.movePassageUp!==undefined?-1:1));return renderScopeDetail();}});
let scopeDrag=null;
document.addEventListener('dragstart',event=>{const passage=event.target.closest('[data-scope-passage]'),group=event.target.closest('[data-scope-group-card]');if(passage)scopeDrag={type:'passage',id:passage.dataset.scopePassage};else if(group)scopeDrag={type:'group',id:group.dataset.scopeGroupCard};else return;event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/plain',scopeDrag.id);});
document.addEventListener('dragover',event=>{if(scopeDrag&&event.target.closest('[data-scope-dropzone],[data-scope-group-card]')){event.preventDefault();event.dataTransfer.dropEffect='move';}});
document.addEventListener('drop',event=>{const layout=state.scopeEditor?.layout;if(!scopeDrag||!layout)return;event.preventDefault();if(scopeDrag.type==='group'){const target=event.target.closest('[data-scope-group-card]');if(target){moveGroup(layout,scopeDrag.id,layout.groups.findIndex(group=>group.key===target.dataset.scopeGroupCard));renderScopeDetail();}}else{const zone=event.target.closest('[data-scope-dropzone]'),target=event.target.closest('[data-scope-passage]');if(zone){const groupKey=zone.dataset.scopeDropzone||UNGROUPED,list=groupKey?layout.groups.find(group=>group.key===groupKey)?.passageIds:layout.ungrouped,sourceList=layout.groups.find(group=>group.passageIds.includes(scopeDrag.id))?.passageIds||layout.ungrouped,sourceIndex=sourceList.indexOf(scopeDrag.id);let targetIndex=target?list.indexOf(target.dataset.scopePassage):list.length;if(sourceList===list&&sourceIndex>=0&&sourceIndex<targetIndex)targetIndex-=1;movePassage(layout,scopeDrag.id,groupKey,targetIndex);renderScopeDetail();}}scopeDrag=null;});
document.addEventListener('dragend',()=>{scopeDrag=null;});
document.addEventListener('click',async event=>{const button=event.target.closest('button');if(event.target.closest('[data-close-delete]'))return closeDelete();if(event.target.closest('[data-close-passage]'))return closePassage();if(button?.hasAttribute('data-regenerate-all'))return regenerateAllDeterministic();if(button?.dataset.regenerateDeterministic)return regenerateDeterministic(button.dataset.regenerateDeterministic);if(button?.dataset.canonicalKind!==undefined){capturePassageRows();const at=Number(button.dataset.canonicalKind),order=['SENTENCE','TITLE','SUBTITLE'],row=state.passageEditor.rows[at];row.blockType=order[(order.indexOf(row.blockType)+1)%order.length];return renderPassageEditor();}if(button?.dataset.easyTranslation!==undefined){capturePassageRows();const editor=state.passageEditor,at=Number(button.dataset.easyTranslation),row=editor.rows[at],input=document.querySelector(`[data-canonical-ko="${at}"]`),previous=input?.value;button.disabled=true;const result=await safely(()=>call('studio_easy_translation',{passageId:state.passageEditorId,sentenceId:row.id},state.token,'쉬운 해석을 만드는 중…'));button.disabled=false;if(result&&state.passageEditor===editor&&editor.rows[at]===row&&input?.isConnected&&input.value===previous){row.translation=result.translation;input.value=result.translation;input.focus();}return;}if(button?.dataset.canonicalDelete!==undefined){capturePassageRows();state.passageEditor.rows.splice(Number(button.dataset.canonicalDelete),1);return renderPassageEditor();}if(button?.dataset.canonicalAdd!==undefined){capturePassageRows();const at=Number(button.dataset.canonicalAdd);state.passageEditor.rows.splice(at+1,0,{id:null,blockType:'SENTENCE',paragraphIndex:state.passageEditor.rows[at]?.paragraphIndex||0,text:'',translation:''});return renderPassageEditor();}if(button?.dataset.factoryDelete!==undefined){captureFactoryRows();state.factoryRows.splice(Number(button.dataset.factoryDelete),1);return renderFactoryReview({job:state.factoryJob});}if(button?.dataset.factoryAddAfter!==undefined){captureFactoryRows();state.factoryRows.splice(Number(button.dataset.factoryAddAfter)+1,0,{text:'',translation:''});return renderFactoryReview({job:state.factoryJob});}if(button?.hasAttribute('data-factory-finalize-incomplete'))return confirmFactory({finalize:true,allowIncomplete:true});if(button?.hasAttribute('data-factory-finalize'))return confirmFactory({finalize:true});if(button?.hasAttribute('data-factory-confirm'))return confirmFactory();if(button?.dataset.regenerateWorkbook)return regenerateFactoryWorkbook(button.dataset.regenerateWorkbook);if(button?.dataset.deleteStudent)return openDelete('student',button.dataset.deleteStudent);if(button?.dataset.deletePassage)return openDelete('passage',button.dataset.deletePassage);if(button?.dataset.openScopeSchool){state.scopeEditor={school:button.dataset.openScopeSchool,grade:button.dataset.openScopeGrade};return route('scope-detail');}if(button?.hasAttribute('data-close-scope-detail')){state.scopeEditor=null;return route('scopes');}if(button?.hasAttribute('data-clearScope')){button.closest('form').querySelectorAll('[name="passageIds"]').forEach(input=>input.checked=false);return;}if(button?.hasAttribute('data-clear-passage-selection')){state.selectedPassageIds.clear();renderPassages();return;}if(button?.dataset.editPassage)return openPassage(button.dataset.editPassage);if(button?.dataset.passagePage){state.passagePage+=button.dataset.passagePage==='next'?1:-1;return renderPassages();}});
document.addEventListener('click',event=>{const period=event.target.closest('[data-learning-period]');if(period){state.learning.period=period.dataset.learningPeriod;state.learning.data=null;return loadLearningProgress();}const student=event.target.closest('[data-open-learning-student]');if(student)return openLearningStudent(student.dataset.openLearningStudent);const attempt=event.target.closest('[data-open-learning-attempt]');if(attempt)return openLearningAttempt(attempt.dataset.openLearningAttempt);if(event.target.closest('[data-close-learning-student]')){state.learning.detail=null;state.learning.replay=null;return renderLearningProgress();}if(event.target.closest('[data-close-learning-attempt]')){state.learning.replay=null;const root=$('#learning-attempt-replay');if(root){root.hidden=true;root.innerHTML='';}}});
document.addEventListener('submit',async event=>{const form=event.target;if(form.id!=='delete-form')return;event.preventDefault();const target=state.deleteTarget;if(!target)return;const op={student:'delete_student',passage:'delete_passage'}[target.targetType],idKey={student:'studentId',passage:'passageId'}[target.targetType];const data=await safely(()=>call(op,{[idKey]:target.targetId},state.token,'연결 데이터를 함께 삭제하는 중…'));if(data){closeDelete();state.selectedPassageIds.delete(target.targetId);await loadAdmin();toast('연결된 READY 데이터까지 삭제했습니다.');}});
document.addEventListener('click',async event=>{const button=event.target.closest('button');if(!button)return;if(button.dataset.route)return route(button.dataset.route);if(button.id==='theme-toggle')return applyTheme(document.body.classList.contains('dark')?'light':'dark');if(button.id==='admin-logout')return logout();if(button.id==='refresh-progress'){state.learning.data=null;return loadLearningProgress();}if(['refresh-admin','refresh-passages','refresh-exams'].includes(button.id))return loadAdmin();});
document.addEventListener('submit',event=>{if(event.target.id!=='factory-start-form')return;event.preventDefault();startFactory(event.target);});
document.addEventListener('submit',async event=>{if(event.target.id!=='update-passage-form')return;event.preventDefault();event.stopImmediatePropagation();capturePassageRows();const values=Object.fromEntries(new FormData(event.target)),data=await safely(()=>call('save_passage_canonical',{...values,passageId:state.passageEditorId,rows:state.passageEditor.rows},state.token,'Passage를 저장하고 Deterministic Workbook을 생성하는 중…'));if(!data)return;if(data.regenerationFailed){state.passageEditor.passage={...state.passageEditor.passage,canonical_revision:data.revision,deterministic_status:'failed',deterministic_error:data.error,ai_regeneration_required:true};renderPassageEditor();await loadAdmin();toast('Passage는 저장했고 기존 Workbook은 유지했습니다.');return;}const id=state.passageEditorId;await loadAdmin();await openPassage(id);toast('저장했습니다. 변경 문장만 Authoring에서 검토하세요.');},true);
document.addEventListener('click',event=>{const button=event.target.closest('[data-clear-scope]');if(!button)return;button.closest('form')?.querySelectorAll('[name="passageIds"]').forEach(input=>input.checked=false);});
document.addEventListener('submit',async event=>{event.preventDefault();const form=event.target,formData=new FormData(form),values=Object.fromEntries(formData);if(form.id==='admin-login-form')return login(form);if(form.id==='create-student-form'){const data=await safely(()=>call('create_student',values));if(data){form.reset();await loadAdmin();}return;}if(form.id==='assign-passages-to-scope'){const passageIds=[...state.selectedPassageIds],data=await safely(()=>call('assign_scope_passages',{school:values.school,grade:values.grade,passageIds},state.token,'시험범위에 지문을 배정하는 중…'));if(data){state.selectedPassageIds.clear();await loadAdmin();route('scopes');toast(`${passageIds.length}개 지문을 배정했습니다.`);}return;}if(form.hasAttribute('data-set-scope-layout')){const editor=state.scopeEditor,scope=state.data.exams.find(item=>item.school===editor.school&&item.grade===editor.grade),layout=flattenScopeLayout(editor.layout),emptyGroups=emptyGroupDefinitions(editor.layout);if(editor.layout.groups.some(group=>!group.label.trim()))return toast('묶음 이름을 입력해 주세요.');const data=await safely(()=>call('set_scope_layout',{examId:scope.id,layout,emptyGroups},state.token,'묶음과 순서를 저장하는 중…'));if(data){await loadAdmin();state.scopeEditor={school:editor.school,grade:editor.grade};renderScopeDetail();toast('시험범위 묶음과 순서를 저장했습니다.');}return;}if(form.id==='update-passage-form'){const data=await safely(()=>call('update_passage',{...values,passageId:state.passageEditorId},state.token,'지문을 저장하는 중…'));if(data){closePassage();await loadAdmin();toast('지문 정보를 저장했습니다.');}return;}if(form.dataset.resetCode){const data=await safely(()=>call('set_student_code',{studentId:form.dataset.resetCode,code:values.code}));if(data){form.reset();toast('학생 코드를 변경하고 기존 학생 세션을 종료했습니다.');}return;}});
document.addEventListener('keydown',event=>{const student=event.target.closest?.('[data-open-learning-student]');if(student&&(event.key==='Enter'||event.key===' ')){event.preventDefault();return openLearningStudent(student.dataset.openLearningStudent);}if(event.key!=='Escape')return;if(state.route==='passage-editor')closePassage();if($('#delete-modal').classList.contains('on'))closeDelete();});
initStudio({api:(op,data)=>safely(()=>call(op,data)),toast,refresh:loadAdmin,openPassage});
document.addEventListener('click',event=>{const button=event.target.closest('[data-edit-student]');if(!button)return;const student=state.data.students.find(s=>s.id===button.dataset.editStudent);button.closest('tr').insertAdjacentHTML('afterend',`<tr><td colspan="4"><form data-edit-student-form="${student.id}" class="form-grid"><label>이름<input name="name" value="${escapeHtml(student.name)}" required maxlength="40"></label><label>학교<input name="school" value="${escapeHtml(student.school)}" required maxlength="80"></label><label>학년<select name="grade">${['1학년','2학년','3학년'].map(g=>`<option ${g===student.grade?'selected':''}>${g}</option>`).join('')}</select></label><button class="button primary" type="submit">정보 저장</button></form></td></tr>`);button.disabled=true;});
document.addEventListener('submit',async event=>{const form=event.target;if(!form.dataset.editStudentForm)return;event.preventDefault();const result=await safely(()=>call('update_student',{studentId:form.dataset.editStudentForm,...Object.fromEntries(new FormData(form))}));if(result){await loadAdmin();toast('학생 정보를 저장했습니다.');}});
applyTheme(localStorage.getItem('ready-theme')||(matchMedia('(prefers-color-scheme:dark)').matches?'dark':'light'));try{const previous=JSON.parse(localStorage.getItem(SESSION_KEY)||'null');if(previous?.token){state.token=previous.token;loadAdmin();}else showLogin();}catch{clearSession();showLogin();}
